/* 业务数据只经异步模拟接口；独立会话状态，不调用旧closeReport。 */
(function(root){const seed=typeof module==='object'&&module.exports?require('./problem-data.js'):root.EAM_PROBLEM_JSON;
const workSeed=typeof module==='object'&&module.exports?require('./work-data.js'):root.EAM_WORK_JSON;const workRules=typeof module==='object'&&module.exports?require('./work-rules.js'):root.EamWorkRules;
const copy=x=>JSON.parse(JSON.stringify(x));
function createApi(options={}){let data={...copy(seed),...copy(workSeed)};const context=options.context||(()=>({role:'engineer',person:'P05',scenario:'normal'}));
const storage=options.storage,key='eam-problems-v1';if(storage){try{const saved=JSON.parse(storage.getItem(key));if(saved?.schema===1)data={...data,...saved.data};}catch{}}
if(!data.people.some(p=>p.id==='P08'))data.people.push({id:'P08',name:'吴工'});if(!data.people.some(p=>p.id==='P12'))data.people.push({id:'P12',name:'外包张工'});
for(const r of data.discoveries){if(r.priority==='urgent'){r.sourcePriority='urgent';r.priority='high';}r.source=({manual:'现场发现',inspection:'点检发现',special:'专项检查'})[r.source]||r.source;}
const must=(ok,message)=>{if(!ok)throw new Error(message);};
async function request(method,path,body={}){await new Promise(r=>setTimeout(r,options.delay??180));const ctx=context();must(ctx.role&&ctx.person&&ctx.scenario!=='forbidden','无访问权限');must(ctx.scenario!=='loading','仍在读取，请稍后重试');
const [kind,id,action]=path.split('/').filter(Boolean);must(['discoveries','defects','failures','equipment','people','work-orders','hazards','work-config','work-order-candidates'].includes(kind),'接口不存在');
if(method==='GET'&&kind==='discoveries'&&options.legacyReports){for(const r of options.legacyReports()){const importedId='LEG-'+r.id;if(!data.discoveries.some(d=>d.id===importedId)){data.discoveries.push({id:importedId,equipmentId:r.equipmentId||'EQ-001',description:r.description,source:({manual:'现场发现',inspection:'点检发现',special:'专项检查'})[r.source]||r.source||'旧点检来源',sourceId:r.sourceId,legacyReportId:r.id,part:r.part,sourcePriority:r.severity,priority:r.severity==='urgent'?'high':r.severity||'medium',status:'submitted',ownerId:'P05',reporter:r.reporterId,occurredAt:r.observedAt||r.receivedAt,evidence:(r.evidence||'未记录额外证据')+'；旧报告引用 '+r.id+'；原结果保留。旧关闭结论不作为新问题验证。',links:[],version:1});}}if(storage)storage.setItem(key,JSON.stringify({schema:1,data}));}
if(method==='GET'&&kind==='work-order-candidates')return {rows:['defects','failures','hazards'].flatMap(k=>data[k].filter(p=>p.status!=='closed').map(p=>({kind:k,...copy(p)})))};
if(method==='GET'&&kind==='work-config')return copy(data.workConfig);
if(method==='GET'&&['work-orders','hazards'].includes(kind)){let rows=kind==='work-orders'?data.workOrders:data.hazards;if(kind==='work-orders'&&['technician','contractor'].includes(ctx.role))rows=rows.filter(o=>o.assigneeId===ctx.person);if(ctx.scenario==='empty')rows=[];if(id){const r=rows.find(r=>r.id===id);must(r,'记录不存在或不在指派范围');return {...workRules.decorate(kind,r,data,ctx),audit:copy(data.audit.filter(a=>a.objectId===id))};}return {rows:rows.map(r=>workRules.decorate(kind,r,data,ctx)),audit:copy(data.audit)};}
if(method==='GET'){const rows=ctx.scenario==='empty'?[]:data[kind];if(id){const record=rows.find(r=>r.id===id);must(record,'记录不存在');return copy(record);}return {rows:copy(rows),audit:copy(data.audit)};}
must(ctx.scenario!=='failure','模拟提交失败，数据未保存');must(ctx.scenario!=='conflict','版本冲突，请重新读取');must(method==='POST','不支持该方法');
if(['work-orders','hazards'].includes(kind)){const next=copy(data);const result=workRules.command(next,ctx,kind,id,action,body);if(!result.unchanged)commit(next,result.record,action||'create_work',body.reason,ctx,result.affected);return workRules.decorate(kind,result.record,next,ctx);}
if(kind==='discoveries'&&!id&&(body.sourceType==='maintenance'||body.sourceTaskId||body.sourceItemId)){must(body.sourceType==='maintenance','保养来源类型无效');const resolver=options.maintenanceSource||(root.EamMaintenanceApi?(b=>root.EamMaintenanceApi.request('GET','/maintenance/tasks/'+encodeURIComponent(b.sourceTaskId))):null);must(resolver,'保养任务来源未接入');const task=await resolver(body);must(task&&task.equipmentId===body.equipmentId&&task.executionVersion===body.executionVersion&&task.snapshot.items.some(i=>i.id===body.sourceItemId)&&task.status==='in_progress'&&[task.primaryPersonId,...task.collaboratorIds].includes(ctx.person),'保养任务来源或执行权限不符');const sourceKey=[body.sourceTaskId,body.sourceItemId,body.executionVersion,body.idempotencyKey].join(':');const old=data.discoveries.find(d=>d.maintenanceSourceKey===sourceKey);if(old){must(old.maintenancePayload===JSON.stringify(body),'来源幂等键内容不同');return copy(old);}}
const next=copy(data),list=next[kind],record=list.find(r=>r.id===id);const admin=['engineer','supervisor'].includes(ctx.role);
const required=(value,label)=>must(typeof value==='string'&&value.trim(),label+'必填');
const newId=(prefix,items)=>prefix+'-'+(Math.max(1000,...items.map(x=>Number(x.id.split('-')[1])||0))+1);
const memoKey=body.idempotencyKey?ctx.person+':'+kind+':'+body.idempotencyKey:null;
if(!id){must(kind==='discoveries','仅发现支持现场新增');required(body.idempotencyKey,'幂等键');const old=next.requests.find(r=>r.key===memoKey);if(old){must(old.payload===JSON.stringify(body),'幂等键与原请求内容不一致');return copy(list.find(x=>x.id===old.id));}
required(body.description,'异常描述');required(body.occurredAt,'发生时间');must(Number.isFinite(Date.parse(body.occurredAt)),'发生时间无效');must(!body.priority||['low','medium','high'].includes(body.priority),'优先级无效');must(body.description.length<=1000,'描述最多1000字');must(next.equipment.some(e=>e.id===body.equipmentId),'设备不存在');must(['operator','inspector','technician','engineer','supervisor','safety'].includes(ctx.role)||(ctx.role==='contractor'&&body.sourceType==='maintenance'),'无新增权限');
const row={id:newId('AB',list),equipmentId:body.equipmentId,description:body.description.trim(),source:body.source||'现场发现',part:body.part||'未指定部位',priority:body.priority||'medium',status:body.draft?'draft':'submitted',ownerId:ctx.person,reporter:ctx.person,occurredAt:body.occurredAt,evidence:body.evidence||'',emergencyAction:body.emergencyAction||'',links:[],version:1};if(body.sourceType==='maintenance')Object.assign(row,{sourceType:'maintenance',sourceTaskId:body.sourceTaskId,sourceItemId:body.sourceItemId,executionVersion:body.executionVersion,maintenanceSourceKey:[body.sourceTaskId,body.sourceItemId,body.executionVersion,body.idempotencyKey].join(':'),maintenancePayload:JSON.stringify(body)});list.push(row);next.requests.push({key:memoKey,id:row.id,payload:JSON.stringify(body)});commit(next,row,'create',body.description,ctx);return copy(row);}
must(record,'记录不存在');must(record.version===Number(body.expectedVersion),'版本冲突，请重新读取');required(body.reason,'操作意见');must(body.reason.length<=1000,'意见最多1000字');
if(kind==='discoveries'&&action==='archive'){must(admin,'无归档权限');must(['submitted','triaged'].includes(record.status),'当前状态不能归档');required(body.evidence,'归档核实证据');if(record.links.length){must(record.links.every(ref=>next[ref.kind]?.find(p=>p.id===ref.id)?.status==='closed'),'关联问题尚未全部关闭，不能归档');}else must(record.priority!=='high','高优先级发现须先核实并关联问题');record.status='archived';record.archiveReason=body.reason;record.archiveEvidence=body.evidence;record.archivedBy=ctx.person;record.archivedAt=new Date().toISOString();
}else if(kind==='discoveries'&&action==='triage'){must(admin,'无分诊权限');must(record.status==='submitted','当前状态不能分诊');must(Array.isArray(body.types)&&body.types.every(k=>['defects','failures','hazards'].includes(k)),'问题类型无效');must(new Set(body.types).size===body.types.length,'问题类型重复');must(next.people.some(p=>p.id===body.ownerId),'责任人不存在');required(body.dueAt,'处置期限');must(Number.isFinite(Date.parse(body.dueAt)),'期限无效');
record.links=[];for(const k of body.types){const prefix=k==='defects'?'DF':k==='failures'?'FL':'HZ';const row={id:newId(prefix,next[k]),equipmentId:record.equipmentId,description:record.description,part:record.part,priority:record.priority,status:k==='failures'?'confirmed':'open',ownerId:body.ownerId,dueAt:body.dueAt,occurredAt:record.occurredAt,evidence:body.reason,links:[{kind:'discoveries',id:record.id}],version:1};if(k==='failures'){required(body.failureMode,'失效模式');required(body.impact,'功能影响');row.failureMode=body.failureMode;row.impact=body.impact;}if(k==='hazards'){row.authority='local';row.major=null;row.assessmentRequired=true;row.restriction={type:'safety',scope:'待风险核实的相关作业',status:'active',reason:'隐患待核实与复查'};}next[k].push(row);record.links.push({kind:k,id:row.id});}
if(body.existingId){const existing=next.defects.find(x=>x.id===body.existingId);must(existing&&existing.equipmentId===record.equipmentId&&existing.status!=='closed','已有缺陷不适用');must(!body.types.includes('defects'),'关联已有缺陷时不能重复新建缺陷');record.links.push({kind:'defects',id:existing.id});existing.links.push({kind:'discoveries',id:record.id});existing.version++;}
must(record.links.length||record.priority!=='high','高优先级发现不能直接无问题归档，须核实并关联问题');record.status=record.links.length?'triaged':'archived';record.triageReason=body.reason;
}else if(kind==='defects'&&action==='submit'){must(admin||ctx.person===record.ownerId||ctx.role==='technician','无提交权限');must(['open','in_progress'].includes(record.status),'当前状态不能提交验证');required(body.evidence,'处置证据');record.status='pending_verification';record.executorId=ctx.person;record.evidence=body.evidence;
}else if(kind==='failures'&&action==='restore'){must(admin||ctx.role==='technician','无恢复记录权限');must(record.status==='confirmed','当前状态不能记录恢复');required(body.evidence,'恢复证据');required(body.restoredAt,'恢复时间');must(Number.isFinite(Date.parse(body.restoredAt))&&Date.parse(body.restoredAt)>=Date.parse(record.occurredAt)&&Date.parse(body.restoredAt)<=Date.now(),'恢复时间无效或早于失效时间');record.restoredAt=body.restoredAt;record.evidence=body.evidence;record.executorId=ctx.person;record.status='restored';
}else if(['defects','failures'].includes(kind)&&action==='verify'){must(admin,'无验证权限');must(record.status===(kind==='defects'?'pending_verification':'restored'),'当前状态不能验证');must(ctx.person!==record.executorId,'必须由独立人员验证');required(body.evidence,'验证证据');must(['pass','return'].includes(body.decision),'验证结论无效');record.status=body.decision==='pass'?'closed':kind==='defects'?'in_progress':'confirmed';if(body.decision==='pass')record.verifiedBy=ctx.person;else{delete record.verifiedBy;if(kind==='failures')delete record.restoredAt;}record.verification={reason:body.reason,evidence:body.evidence,decision:body.decision,at:new Date().toISOString()};
}else throw new Error('操作尚未实现或不适用于此对象');
record.version++;commit(next,record,action,body.reason,ctx);return copy(record);
}
function commit(next,row,action,reason,ctx,affected=[]){for(const changed of [row,...affected]){const original=['discoveries','defects','failures','hazards','workOrders'].flatMap(k=>data[k]||[]).find(r=>r.id===changed.id);next.audit.push({before:original?copy(original):null,after:copy(changed),objectId:changed.id,action:changed.id===row.id?action:action+'_linked',reason,actorId:ctx.person,at:new Date().toISOString(),version:changed.version});}if(storage)storage.setItem(key,JSON.stringify({schema:1,data:next}));data=next;}
return {request};}
const api={createApi};if(typeof module==='object'&&module.exports)module.exports=api;else{root.EamProblemApi=createApi({context:()=>root.Eam.s,storage:sessionStorage,legacyReports:()=>root.Eam.s.reports||[]});}
})(typeof window==='undefined'?globalThis:window);
